import math


def summarize_samples(samples):
    try:
        groups = list(samples)
    except TypeError as exc:
        raise ValueError("samples must be iterable") from exc
    if not groups:
        raise ValueError("at least one sample is required")

    output = []
    for group in groups:
        try:
            values = list(group)
        except TypeError as exc:
            raise ValueError("each sample must be iterable") from exc
        if not values:
            raise ValueError("samples cannot be empty")
        if any(isinstance(v, bool) or not isinstance(v, (int, float)) or not math.isfinite(v) for v in values):
            raise ValueError("sample values must be finite numbers")
        count = len(values)
        mean = sum(values) / count
        variance = sum((value - mean) ** 2 for value in values) / (count - 1)
        deviation = math.sqrt(variance)
        z_scores = [0.0] * count if deviation == 0 else [(value - mean) / deviation for value in values]
        minimum = min(values)
        maximum = max(values)
        output.append({
            "count": count,
            "minimum": minimum,
            "maximum": maximum,
            "span": maximum - minimum,
            "mean": mean,
            "variance": variance,
            "deviation": deviation,
            "z_scores": z_scores,
        })
    return output

